/* @lc app=leetcode id=3514 lang=kotlin */ class Solution { fun uniqueXorTriplets(nums: IntArray): Int = nums.distinct().toIntArray().let { d -> BooleanArray(2048).also { p -> d.forEach { a -> d.forEach { b -> p[a xor b] = true } } }.let { p -> BooleanArray(2048).also { q -> (0 until 2048).filter { p[it] }.forEach { x -> d.forEach { c -> q[x xor c] = true } } }.count { it } } } }